--
-- Table structure for table `articles`
--

DROP TABLE IF EXISTS `articles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `articles` (
  `id` int NOT NULL AUTO_INCREMENT,
  `manuscript_code` varchar(100) DEFAULT NULL,
  `title` varchar(500) NOT NULL,
  `abstract` text,
  `keywords` text,
  `article_type` varchar(100) DEFAULT NULL,
  `status` varchar(50) DEFAULT NULL,
  `submitted_by` int DEFAULT NULL,
  `journal_id` int DEFAULT NULL,
  `has_funders` tinyint(1) DEFAULT NULL,
  `special_issue` varchar(255) DEFAULT NULL,
  `suggested_reviewers` text,
  `created_at` datetime DEFAULT (now()),
  `updated_at` datetime DEFAULT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `accepted_at` datetime DEFAULT NULL,
  `rejected_at` datetime DEFAULT NULL,
  `views_count` int DEFAULT '0',
  `downloads_count` int DEFAULT '0',
  `similarity_score` float DEFAULT NULL,
  `similarity_report_url` varchar(500) DEFAULT NULL,
  `screening_checklist` text,
  `screening_notes` text,
  `handling_editor_id` int DEFAULT NULL,
  `doi` varchar(255) DEFAULT NULL,
  `proof_approved_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_articles_manuscript_code` (`manuscript_code`),
  KEY `submitted_by` (`submitted_by`),
  KEY `journal_id` (`journal_id`),
  KEY `ix_articles_id` (`id`),
  KEY `fk_handling_editor` (`handling_editor_id`),
  CONSTRAINT `articles_ibfk_1` FOREIGN KEY (`submitted_by`) REFERENCES `users` (`id`),
  CONSTRAINT `articles_ibfk_2` FOREIGN KEY (`journal_id`) REFERENCES `journals` (`id`),
  CONSTRAINT `fk_handling_editor` FOREIGN KEY (`handling_editor_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=352 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
