INSERT INTO `articles` VALUES (1,'JST-2026-0001','NỀN TẢNG TRUY XUẤT VÀ MINH BẠCH CHUỖI CUNG ỨNG NÔNG SẢN ĐỊA PHƯƠNG DỰA TRÊN BLOCKCHAIN','Nghiên cứu này thiết kế và triển khai thực nghiệm nền tảng truy xuất chuỗi cung ứng nông sản sử dụng Kiến trúc lưu trữ lai (Hybrid Storage) kết hợp với cơ chế Ghi kép (Dual-Write) và thuật toán băm SHA-256. Giải pháp đạt sự cân bằng tối ưu giữa hiệu năng truy vấn của cơ sở dữ liệu quan hệ (MySQL) với thời gian phản hồi API nhanh chóng (80–200 ms) và tính minh bạch, bất biến của mạng chuỗi khối (Ethereum). Kết quả thực nghiệm đối chứng trên mạng Sepolia cho thấy hệ thống giúp giảm ≈ 50% lượng Gas tiêu thụ (từ 442.519 xuống còn 223.247 Gas) so với phương thức lưu trữ on-chain truyền thống. Nghiên cứu cũng đề xuất Mô hình tính điểm tin cậy (Trust Score Model) làm điểm nhấn riêng, đạt mức độ tin cậy 83,3% trong Case Study nông sản \"Nhãn Hưng Yên\" (dữ liệu mô phỏng) khi thiếu một mốc sự kiện cuối. Hệ thống chứng minh khả năng phát hiện tức thời các hành vi sửa đổi dữ liệu trái phép (trạng thái MISMATCH) và thảo luận hướng xử lý lỗi \"Garbage In – Garbage Out\" qua xác thực chéo và tích hợp IoT.',' Blockchain, Kiến trúc lưu trữ lai, Truy xuất nguồn gốc, Ghi kép, Trust Score, Nông sản địa phương','Review Article','SUBMITTED',3,1,0,'','','2026-08-18 08:47:07','2026-08-18 08:49:17','2026-08-18 01:49:17',NULL,NULL,0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2,NULL,'NỀN TẢNG TRUY XUẤT VÀ MINH BẠCH CHUỖI CUNG ỨNG NÔNG SẢN ĐỊA PHƯƠNG DỰA TRÊN BLOCKCHAIN','Nghiên cứu này thiết kế và triển khai thực nghiệm nền tảng truy xuất chuỗi cung ứng nông sản sử dụng Kiến trúc lưu trữ lai (Hybrid Storage) kết hợp với cơ chế Ghi kép (Dual-Write) và thuật toán băm SHA-256. Giải pháp đạt sự cân bằng tối ưu giữa hiệu năng truy vấn của cơ sở dữ liệu quan hệ (MySQL) với thời gian phản hồi API nhanh chóng (80–200 ms) và tính minh bạch, bất biến của mạng chuỗi khối (Ethereum). Kết quả thực nghiệm đối chứng trên mạng Sepolia cho thấy hệ thống giúp giảm ≈ 50% lượng Gas tiêu thụ (từ 442.519 xuống còn 223.247 Gas) so với phương thức lưu trữ on-chain truyền thống. Nghiên cứu cũng đề xuất Mô hình tính điểm tin cậy (Trust Score Model) làm điểm nhấn riêng, đạt mức độ tin cậy 83,3% trong Case Study nông sản \"Nhãn Hưng Yên\" (dữ liệu mô phỏng) khi thiếu một mốc sự kiện cuối. Hệ thống chứng minh khả năng phát hiện tức thời các hành vi sửa đổi dữ liệu trái phép (trạng thái MISMATCH) và thảo luận hướng xử lý lỗi \"Garbage In – Garbage Out\" qua xác thực chéo và tích hợp IoT.','','Short Communication','DRAFT',3,1,0,NULL,NULL,'2026-08-18 13:39:37','2026-08-18 13:40:35',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(3,NULL,'Untitled','','','Review Article','DRAFT',3,1,0,NULL,NULL,'2026-08-18 13:52:20',NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(4,NULL,'NỀN TẢNG TRUY XUẤT VÀ MINH BẠCH CHUỖI CUNG ỨNG NÔNG SẢN ĐỊA PHƯƠNG DỰA TRÊN BLOCKCHAIN','Nghiên cứu này thiết kế và triển khai thực nghiệm nền tảng truy xuất chuỗi cung ứng nông sản sử dụng Kiến trúc lưu trữ lai (Hybrid Storage) kết hợp với cơ chế Ghi kép (Dual-Write) và thuật toán băm SHA-256. Giải pháp đạt sự cân bằng tối ưu giữa hiệu năng truy vấn của cơ sở dữ liệu quan hệ (MySQL) với thời gian phản hồi API nhanh chóng (80–200 ms) và tính minh bạch, bất biến của mạng chuỗi khối (Ethereum). Kết quả thực nghiệm đối chứng trên mạng Sepolia cho thấy hệ thống giúp giảm ≈ 50% lượng Gas tiêu thụ (từ 442.519 xuống còn 223.247 Gas) so với phương thức lưu trữ on-chain truyền thống. Nghiên cứu cũng đề xuất Mô hình tính điểm tin cậy (Trust Score Model) làm điểm nhấn riêng, đạt mức độ tin cậy 83,3% trong Case Study nông sản \"Nhãn Hưng Yên\" (dữ liệu mô phỏng) khi thiếu một mốc sự kiện cuối. Hệ thống chứng minh khả năng phát hiện tức thời các hành vi sửa đổi dữ liệu trái phép (trạng thái MISMATCH) và thảo luận hướng xử lý lỗi \"Garbage In – Garbage Out\" qua xác thực chéo và tích hợp IoT.','','Review Article','DRAFT',3,1,0,NULL,NULL,'2026-08-18 14:13:56','2026-08-18 14:14:53'