INSERT INTO `rules` VALUES (1,'SUBMISSION_TERMS','copyright','Tôi đồng ý với các điều khoản bản quyền và cấp phép của tạp chí.',NULL,1,1,1,'2026-08-24 16:17:38',NULL),(2,'SUBMISSION_TERMS','original','Tôi xác nhận rằng bản thảo này là bản gốc và không được xem xét ở nơi khác.',NULL,2,1,1,'2026-08-24 16:17:38',NULL),(3,'SUBMISSION_TERMS','genai','Tôi cam kết công khai việc sử dụng công cụ AI tạo sinh (Generative AI) trong quá trình chuẩn bị bản thảo này (nếu có), theo đúng quy định GenAI của tạp chí.',NULL,3,1,1,'2026-08-24 16:17:38',NULL),(4,'DESK_SCREENING','has_required_files','Hồ sơ nộp đầy đủ các tệp bắt buộc','Đã có Bản thảo chính (Manuscript), Trang tiêu đề (Title Page) và Giấy cam kết/Xung đột lợi ích (CoI).',1,1,1,'2026-08-24 16:17:38',NULL),(5,'DESK_SCREENING','is_anonymous_double_blind','Bản thảo chính đã ẩn danh hoàn toàn (Double-blind check)','Tệp Main Manuscript đã xóa bỏ tên tác giả, đơn vị công tác, lời cảm ơn và thông tin liên hệ.',2,1,1,'2026-08-24 16:17:38',NULL),(6,'DESK_SCREENING','is_within_scope','Phù hợp tôn chỉ & phạm vi của Tạp chí (Scope check)','Chủ đề bài viết thuộc các lĩnh vực xuất bản của Tạp chí BDU và có hàm lượng khoa học rõ ràng.',3,1,1,'2026-08-24 16:17:38',NULL),(7,'DESK_SCREENING','passed_similarity_threshold','Đạt tiêu chuẩn chỉ số trùng lặp / đạo văn (< 20%)','Đã kiểm tra qua hệ thống chống trùng lặp, không có dấu hiệu sao chép đoạn văn lớn trái phép.',4,1,1,'2026-08-24 16:17:38',NULL),(8,'DESK_SCREENING','passed_formatting_standards','Đúng định dạng văn bản & trích dẫn chuẩn BDU','Đúng font chữ, quy cách bảng biểu, hình ảnh và danh mục tài liệu tham khảo theo quy định.',5,1,1,'2026-08-24 16:17:38',NULL),(9,'REVIEW_CRITERIA','originality','Originality','Evaluate the novelty and scientific significance...',1,1,1,'2026-08-24 16:17:38',NULL),(10,'REVIEW_CRITERIA','relationship_to_literature','Relationship to Literature','Are relevant studies appropriately cited and contextualized?',2,1,1,'2026-08-24 16:17:38',NULL),(11,'REVIEW_CRITERIA','methodology','Methodology','Is the research design sound and replicable?',3,1,1,'2026-08-24 16:17:38',NULL),(12,'REVIEW_CRITERIA','results','Results','Are the findings clearly presented and supported by data?',4,1,1,'2026-08-24 16:17:38',NULL),(13,'REVIEW_CRITERIA','implications','Implications for research, practice and/or society','What is the impact and contribution of this work?',5,1,1,'2026-08-24 16:17:38',NULL),(14,'REVIEW_CRITERIA','quality_of_communication','Quality of Communication','Clarity of writing, terminology, structure, and figures.',6,1,1,'2026-08-24 16:17:38',NULL);
